from pathlib import Path
import sys,datetime,json,contextlib
from zoneinfo import ZoneInfo
p=Path('/home/cofallen/Code/毕业设计/experiments/E002_original_controller');case=sys.argv[1]
out=p/'outputs'/('held_trial_'+case+'_'+datetime.datetime.now(ZoneInfo('Asia/Shanghai')).strftime('%Y%m%d_%H%M%S_%f'));out.mkdir()
sys.path.insert(0,str(p));import controller,mujoco,mujoco.viewer
Current=None;original=controller.Teleop
class Recorded(original):
 def __init__(self,*a,**kw):
  global Current
  super().__init__(*a,**kw);Current=self
class Keys:
 def __init__(self):self.jumped=False
 def on_key(self,key):pass
 def poll(self):
  t=Current.clock;held=set();actions=[]
  if case=='forward' and 2<=t<5:held={'w'}
  if case=='backward' and 2<=t<5:held={'s'}
  if case=='legs':
   if 1<=t<3:held={'q'}
   if 4<=t<6:held={'e'}
  if case=='jump' and t>=2 and not self.jumped:actions=['j'];self.jumped=True
  return held,actions
 def close(self):pass
class Window:
 def __init__(self,m,d):self.opt=mujoco.MjvOption();self.cam=mujoco.MjvCamera();self.user_scn=mujoco.MjvScene(m,maxgeom=10)
 def lock(self):return contextlib.nullcontext()
 def set_texts(self,*a):pass
 def is_running(self):return True
 def sync(self):pass
 def close(self):pass
controller.Teleop=Recorded;controller.KeyboardInput=Keys;mujoco.viewer.launch_passive=lambda m,d,**kw:Window(m,d)
controller.time.sleep=lambda s:None
controller.os._exit=lambda n:(_ for _ in ()).throw(SystemExit(n))
argv=[str(p/'controller.py'),'--viewer','--duration','12'];sys.argv=argv
(out/'metadata.json').write_text(json.dumps(dict(case=case,command=argv,scope='Actual main control loop with deterministic held-key schedule; no real GUI or X11 release proof',script=Path(__file__).read_text()),indent=2)+'\n')
try:code=controller.main()
except SystemExit as e:code=e.code
(out/'exit_status.json').write_text(json.dumps(dict(exit_code=code))+'\n');print(out);sys.exit(code)
